// Differential property-based tests: uuid@3 v4() (old) vs crypto.randomUUID() (new).
// Generated by Revenant, recipe uuid3-to-randomuuid. Run with: npx vitest run
import { randomUUID } from "node:crypto";
import { createRequire } from "node:module";
import fc from "fast-check";
import { describe, expect, it } from "vitest";

const require = createRequire(import.meta.url);
const oldV4: () => string = require("uuid/v4");

const V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const batch = fc.integer({ min: 1, max: 200 });

describe("uuid@3 v4() vs crypto.randomUUID() (differential)", () => {
  it("both emit RFC 4122 version-4 strings", () => {
    fc.assert(fc.property(fc.constant(null), () => {
        expect(oldV4()).toMatch(V4);
        expect(randomUUID()).toMatch(V4);
      }), { numRuns: 100 });
  });

  it("same shape: length, hyphen positions, lowercase hex", () => {
    fc.assert(
      fc.property(fc.constant(null), () => {
        const [a, b] = [oldV4(), randomUUID()];
        expect(b).toHaveLength(a.length);
        expect([...b].map((c, i) => (c === "-" ? i : -1)).filter((i) => i >= 0)).toEqual([...a].map((c, i) => (c === "-" ? i : -1)).filter((i) => i >= 0));
        expect(b).toBe(b.toLowerCase());
      }),
      { numRuns: 100 },
    );
  });

  it("no collisions inside a batch for either implementation", () => {
    fc.assert(
      fc.property(batch, (n) => {
        const olds = new Set(Array.from({ length: n }, () => oldV4()));
        const news = new Set(Array.from({ length: n }, () => randomUUID()));
        expect(olds.size).toBe(n);
        expect(news.size).toBe(n);
      }),
      { numRuns: 100 },
    );
  });

  it("variant bits and version nibble are always valid", () => {
    fc.assert(
      fc.property(fc.constant(null), () => {
        for (const id of [oldV4(), randomUUID()]) {
          expect(id[14]).toBe("4");
          expect("89ab").toContain(id[19]);
        }
      }),
      { numRuns: 100 },
    );
  });
});
